import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.BwzYn71E.js";const c=JSON.parse('{"title":"Establishing a Customer Support (Free Consultation and Q&A) Department","description":"","frontmatter":{"translationSource":{"title":"建立售后(义诊答疑)部门","archivedAt":"2026-11-14","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=AnG8YkyaK2VGhXykemIDer","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/establishing-a-customer-support-department"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/establishing-a-customer-support-department"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/establishing-a-customer-support-department"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/establishing-a-customer-support-department"}]]},"headers":[],"relativePath":"establishing-a-customer-support-department.md","filePath":"logistics/src/page-AnG8YkyaK2VGhXykemIDer.md"}'),n={name:"establishing-a-customer-support-department.md"};function r(i,e,p,l,u,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<div class="logistics-content"><h1 id="establishing-a-customer-support-free-consultation-and-q-a-department" tabindex="-1">Establishing a Customer Support (Free Consultation and Q&amp;A) Department <a class="header-anchor" href="#establishing-a-customer-support-free-consultation-and-q-a-department" aria-label="Permalink to &quot;Establishing a Customer Support (Free Consultation and Q&amp;A) Department&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>Content updated: </span><a href="/endfield-skydoc/changelog/capture-2026-11-14T07-40-38-165Z-a1e1e549" title="Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record." aria-label="Content updated: 2026-11-14. Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record."><time datetime="2026-11-14T07:40:39.277Z">2026-11-14</time></a><span class="page-updated-zone"> (China Standard Time)</span></p><blockquote><p>Source page ID: <code>AnG8YkyaK2VGhXykemIDer</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=AnG8YkyaK2VGhXykemIDer" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Due to the summary of issues in the <a href="/endfield-skydoc/issues-with-publishing-results">results-publication process</a>, we decided to establish a customer-support department.</p><p>Collect the names of people involved in after-sales support.</p><p>Establish a relevant group chat.</p><p><span class="mark-grey">The group number should not be posted here; relevant personnel should manually review and invite members.</span></p><p><span class="mark-grey">#言: After-sales support and Q&amp;A should be able to trace root causes and resolve most possible issues. In practice, this requires using reports to backtrack problems with reasonable accuracy, a clear understanding of every module&#39;s functions, and a basic understanding of automatic balancing/adaptive devices. It also requires some spare time to handle questions and learn the necessary knowledge.</span></p><p><span class="mark-grey">#沃: Huh, what about the livestream? 🤔 Wasn&#39;t it written in?</span></p><p><span class="mark-grey">#东: Personally, I think livestreaming is both a troubleshooting method and a safeguard; if you log into someone&#39;s account, stream it to leave a record (</span><span class="mark-grey"><s>? I still feel like venting. All these days of support really have brought plenty of entertainment (?) and a sense of self-worth. Most people can have their problems solved even without reading the docs, but then reading them becomes the support staff&#39;s job (I have looked through the FAQ null times). We send them a screenshot and the problem is solved; if that fails, logging into the account usually finishes the job. What scares me is people who ignore instructions, have their own ideas (not little creative tweaks), or cannot communicate (immortals talking past each other). By comparison, little tweaks do not seem so scary (?!) I came here to solve problems, help people and learn the techniques, so why should I keep losing my temper?</s></span><span class="mark-grey">(Friends who have read this far can probably understand the current state of support x-x.)</span></p><p><span class="mark-grey">#东: The comment section simply is not a place where troubleshooting can be done.</span></p><p><span class="mark-grey">#jnk: </span><a href="/endfield-skydoc/issues-with-publishing-results">Summary of Issues in the Results-Publication Process</a></p><p><span class="mark-grey">#Disadvantage: Current troubleshooting involves many repetitive tasks, such as reminding people about reports. We need ways to avoid these—for example, group-entry questions and announcements explaining the prerequisites for support—to improve efficiency and handle potentially large numbers of requests.</span></p><p><span class="mark-grey">#言: In that case, could we make a bot that monitors group chat and does an initial check for matches with common questions? Ideally, mooch off some free AI (</span></p><p><span class="mark-grey">#东: </span><span class="mark-grey"><s>Feels like QQ Group Assistant would do (?</s></span><span class="mark-grey">Given the restrictions of </span><span class="mark-grey"><u>HarmonyOS</u></span><span class="mark-grey">, I do not think QQ Group Assistant is viable.</span><span class="mark-grey"><s>HarmonyOS is terrible</s></span></p><p><span class="mark-grey">#jnk: 凯 is making a bot. Let&#39;s see how far he&#39;s got (? </span></p><p><span class="mark-grey"><em>#凯: jmy has joined too; this will probably be a long-term project.</em></span><a href="/endfield-skydoc/automatic-support-bot-discussion">Discussion of an Automatic Support Bot</a></p><p><span id="source-block-DheeoJbZgduO0Z9vZfkSv3"></span></p><h2 id="customer-support-q-a-guidelines-to-be-written" tabindex="-1">Customer Support / Q&amp;A Guidelines (to be written <a class="header-anchor" href="#customer-support-q-a-guidelines-to-be-written" aria-label="Permalink to &quot;Customer Support / Q&amp;A Guidelines (to be written&quot;">​</a></h2><p><span class="mark-grey">#东: First, support staff must not snap at users first, and should not snap at them at all—at least be civil when scolding people. Second, if another support person starts snapping, stop them promptly; troubleshooting is not a shouting match. Finally, respect every user, even someone who randomly changes the line and ignores instructions. All beings are equal under compassion. We can choose not to answer, but if we answer, take responsibility and do it properly.</span></p><p><span class="mark-grey">#言: If you do not want to answer, you can ignore it. But once you answer, be prepared to deal with the follow-up questions, or identify clearly who will follow up when handing off a problem you cannot solve. Do not vent or abandon it halfway. (#东: Agreed.)</span></p><p><span id="source-block-MCp3KAJDxAeiKPQNN5mI57"></span></p><h2 id="user-guidelines-to-be-written" tabindex="-1">User Guidelines (to be written <a class="header-anchor" href="#user-guidelines-to-be-written" aria-label="Permalink to &quot;User Guidelines (to be written&quot;">​</a></h2><p><span class="mark-grey">#言: If you have a problem, go to the group chat or the Q&amp;A site first and take the support staff&#39;s answers as authoritative (they are not necessarily absolutely correct, but there is no denying that they are more familiar with production lines than most people and can transfer you to a developer at any time). In other words, do not readily trust replies from other channels, and do not stubbornly insist on your own view with the support staff.</span></p><p><span class="mark-grey"><s>#言: You should look more at the videos and documents for the current production line (documents are normally where blueprints are obtained; note that blueprint codes that appear in the comment section may not be the latest version) and at the videos. The videos show almost every necessary operation, and the documents already answer many common questions. Asking questions that could have been resolved through the above means is an unnecessary burden on the support staff (even if you cannot understand all of it, having made the effort greatly reduces their burden). Please do not consume our enthusiasm and goodwill like this.</s></span></p><p><span class="mark-grey">#言: In principle, we do not accept simple questions asked without first consulting the videos, documentation or in-game encyclopedia. These readily accessible sources answer many common questions. Asking may take you only a few sentences, but large numbers of people repeatedly asking the same questions consume enormous amounts of the support staff&#39;s energy, enthusiasm and goodwill (and, in my view, this is rather unethical). To leave staff enough energy for difficult cases that need them more, questions easily answered by those sources may be ignored. Other helpful group members may answer, but we are not responsible for the accuracy of those answers.</span></p><p>#凯: Some of the senior members think the group should be run democratically, which differs from 言&#39;s view. I hope we can discuss it and reach a conclusion. It is also still unclear when moderators should penalize people and how. Nobody reads the trial group announcement either, so for now every case must at least start with a warning, which makes enforcing the rules inefficient. (王 handles this)</p><p>#JMY: Horror, gore, sexually suggestive and pornographic content are strictly forbidden in the group. The first offense means a 1-day mute; the second means removal and blacklisting.</p><p>＃东: Personally, I don&#39;t really take muting seriously, so sometimes, if something seems excessive, I&#39;ll mute someone briefly as a symbolic gesture. Kicking someone is even less likely. (Why am I being so incoherent?) I feel that what I do could easily turn into throwing my weight around.</p><p><span class="mark-grey">#Disadvantage: Removing people once troubleshooting ends could avoid this to some extent. These rules seem more suited to the main group (? #东: That seems a bit hard on people, and sometimes it is difficult to tell whether troubleshooting has finished (? Wouldn&#39;t that make us an actual hospital?</span><br><span class="mark-grey">#言: Is there no room for a warning? Isn&#39;t that too strict? It is also hard to tell how many times someone has broken the rule. We should not make unenforceable rules.</span></p><p>#jmy: We could set up a separate chat group and move people there after troubleshooting to free up places in the support group.</p><p>#disadvantage: A troubleshooting group really has to do troubleshooting. <span class="mark-grey">Damn, why didn&#39;t you say so earlier? #jmy #东: Damn, why didn&#39;t you say so earlier? #151: Damn, why didn&#39;t you say so earlier?</span></p><p><span class="mark-grey">#Disadvantage: Modifying a production line without fully understanding how it works is strictly forbidden. Asking for support after your own modifications break the factory wastes support staff&#39;s time.</span><br> #言: Or at least explain what modifications you have made.</p><p><span class="mark-grey">#言: Keep unrelated discussion out of the AIC troubleshooting group, including other games, Arknights, gacha, combat rotations and zipline exploits. Mutes may be issued depending on the circumstances.</span></p><p><span class="mark-grey">#东: No attacking support staff</span><span class="mark-grey"><s>—support staff are lower-realm pigfolk</s></span><span class="mark-grey"><br> #言: Why not simply ban personal attacks in the group? Whether against new or old members, support staff, developers or 改区. Administrators decide what counts as a personal attack.</span></p><p>#东: As a rule, no consultations between 2 a.m. and 6 a.m., to protect the support staff. (Wait, don&#39;t we have someone in the US?) <span class="mark-grey">#151: Actually, hardly anyone comes in the early hours (</span></p><p>＃东: I&#39;ve noticed that I set the bar a bit high; the way I exercise authority looks almost like divine rule.</p><p><span class="mark-grey">#jnk: There is rather a lot here. Can you agree on a common position? Or at least first make clear which questions need discussing?</span></p><p><span id="source-block-D4gufk7H4xiLthYE7JHT6d"></span></p><h2 id="qq-group-announcement-subject-to-change" tabindex="-1">QQ Group Announcement (Subject to Change <a class="header-anchor" href="#qq-group-announcement-subject-to-change" aria-label="Permalink to &quot;QQ Group Announcement (Subject to Change&quot;">​</a></h2><p><span class="mark-grey">#东: Is it possible nobody reads from here onward (? #言: Then spell it out clearly below: what gets ignored, what we take no responsibility for, and what gets people kicked out.</span></p><p><span id="source-block-19KQ2zbBPpIjzzgFFxlO2g"></span></p><h3 id="v1-0-0-言" tabindex="-1">v1.0.0 言 <a class="header-anchor" href="#v1-0-0-言" aria-label="Permalink to &quot;v1.0.0 言&quot;">​</a></h3><p><span class="mark-red"><strong>Because this announcement is excessively long, enforcement cannot in practice be as strict as the wording suggests. In most cases, it serves only as grounds for a warning.</strong></span></p><p>Before asking the group for help, we encourage you to watch the videos, read the docs or consult the in-game encyclopedia (apparently this effectively improves the support staff&#39;s opinion of you). Video links are included in the docs, so only the documentation link is given here:<br><a href="/endfield-skydoc/1-5-automatic-maximum-gross-production">1.5 Automatic Maximum Gross Production</a><br> If you want to learn more about how this factory works, the developers have included links to the required reading in that document. Questions arising from studying AIC principles are especially welcome.</p><p>When asking the group for troubleshooting, always show the following items; this greatly improves efficiency:<br> (Star items in the production report to pin them for easy display.) Originium Ore, Ferrium Ore, Cuprium Ore, Cuprium, Ferrium Powder, Cuprium Powder, Dense Originium Powder, Hetonite, Xiranite, Heavy Xiranite, Xircon, Pyrrolite, Separator Core, Cuprium Solution, Cuprium Gas, Hetonite Gas, Pyrrolite Gas, SC Wuling Battery (default order, ascending). Ignoring this may annoy support staff or lead to your question being ignored.</p><p>Sensitive content is forbidden, including horror, gore, sexually suggestive content and financial transactions. Violations lead to immediate removal. Keep unrelated discussion to a minimum, including other games, Arknights, gacha, combat rotations and zipline exploits; mutes may be issued depending on the circumstances.</p><p>Treat the answers from support staff (currently group administrators, excluding the owner) as authoritative. They are not necessarily absolutely correct, but they are more familiar with production lines than most people and can transfer you to developers at any time. Do not readily trust replies from other channels or stubbornly insist on your own view with support staff.</p><p>In principle, we do not accept simple questions asked without first consulting the videos, documentation or in-game encyclopedia. These readily accessible sources answer many common questions. Asking may take you only a few sentences, but large numbers of people repeatedly asking the same questions consume enormous amounts of the support staff&#39;s energy, enthusiasm and goodwill. To leave staff enough energy for difficult cases that need them more, questions easily answered by those sources may be ignored. Other helpful group members may answer, but we are not responsible for the accuracy of those answers.</p><p>Personal attacks are forbidden, whether against new or old group members, support staff or developers. Anyone can report them to members and administrators through a private temporary chat. Confirmed violations lead to a lengthy mute. Please pass on knowledge and kindness rather than hostility, and take responsibility for your words and actions.</p><p>To keep places available for newcomers and new questions, members who have not spoken for a week will be removed at unspecified times each week. If you want to study AIC further, contact an administrator or the group owner through a temporary chat to apply.</p><p>Support staff may ignore questions they do not wish to answer. Once you choose to answer, however, respect the other person&#39;s difficulty and questions throughout and take full responsibility for your assistance. Before transferring a problem you cannot solve, identify the next person responsible and clearly inform the questioner. Do not vent or abandon the issue halfway. If either party breaks the rules, anyone, including those involved, may report it to an administrator or the owner; avoid direct confrontations.</p><p>#Current penalty record: Group D — 开朗的网友 () posted a disturbing image. Action taken: message retracted + muted for 10 minutes.</p><p><strong>Suggestions board</strong>:</p><p>Moderators should state the boundary against unrelated messages during consultations, give one warning for a violation, and explain the reason before imposing a penalty (). Then gently advise on relevant Endfield questions during consultations, warn about unrelated chat, and issue a formal warning for sensitive activities.</p><p>There should be a group announcement, a link to the casual-chat group in the group highlights, and an official statement that this is a Q&amp;A group (consider doing this immediately).</p><p>Penalty tiers: an unrecorded warning/reminder, a recorded warning, a ten-minute mute, a two-hour mute, a one-day mute, and removal from the group. Establish rules for escalating accumulated penalties <span class="mark-grey">(a prior offender receives a harsher penalty next time)</span> and reducing the penalty level over time <span class="mark-grey">(old offenses are not held against someone indefinitely)</span>. Should the rules for moderators be stricter?</p><p>Do not invite bots without permission: a warning for the first offense, a two-hour mute for the next, and removal from the group for another.</p><p><span id="source-block-LYEbZv2WxHGqOloJ0TIlVu"></span></p><h3 id="v1-1-0-jnk" tabindex="-1">v1.1.0 JNK <a class="header-anchor" href="#v1-1-0-jnk" aria-label="Permalink to &quot;v1.1.0 JNK&quot;">​</a></h3><p><strong>Group announcement</strong></p><p>Before asking the group for blueprint support, first watch the videos, read the documentation, or consult the encyclopedia. Documentation link:<br><a href="http://43.108.59.96/" target="_blank" rel="noreferrer">http://43.108.59.96/</a><br> Ask other members for help if those sources do not answer your question.<br> When asking for blueprint support, first show production reports for the following items:<br> (Star items in the report to pin them for easy display.) Originium Ore, Ferrium Ore, Cuprium Ore, Cuprium, Ferrium Powder, Cuprium Powder, Dense Originium Powder, Hetonite, Xiranite, Heavy Xiranite, Xircon, Pyrrolite, Separator Core, Cuprium Solution, Cuprigen, Hetogen, Pyrogen, SC Wuling Battery, Jincao Solution.<br> Do not disrupt a consultation with unrelated messages.<br> We do not guarantee answers from members other than the support staff (group moderators). Please also understand the situation before challenging the support staff.<br> As a rule, consult the videos, documentation, and game encyclopedia before asking. Do not repeat simple questions that already have answers; ask about material that is absent, unclear, or easy to overlook.<br> Sensitive content is prohibited and results in removal from the group. Personal attacks are prohibited even if you were attacked first, and result in a long mute. Chat unrelated to AIC is discouraged. Contact a moderator or the group owner privately if you want to study further or appeal a decision.<br> When the group fills up, remove inactive members, retaining moderators and those active within the past week.</p><p><strong>Group moderation rules</strong></p><p>The central purpose of these rules is to maintain a useful Q&amp;A environment, not exercise divine authority. This has two aspects: preventing group disruption and preserving an atmosphere conducive to answering questions. Every rule should primarily serve that purpose, rather than strictly punish those who cross a line.</p><p>When someone seeks help without providing the required reports and ignores the support staff&#39;s requests, ignore their question. Overly simple questions may also be ignored. <strong>Confrontationally pinging moderators</strong> (tagging them to ask a question but not following their instructions) receives a warning for the first offense, a two-hour mute for the next, and removal for another.</p><p>Once a moderator explicitly declares that a consultation is underway, <strong>unrelated chat that disrupts Q&amp;A is prohibited</strong>; that declaration itself serves as the reminder. The first offense receives a ten-minute mute, the next a one-hour mute, and the next a one-day mute; persistent offenders are removed. [The source includes a stray “6” here.] For the person receiving help, unrelated replies may be dealt with later: only remind/warn them during the consultation and impose any penalty after it ends.</p><p><strong>Sensitive content is prohibited</strong>, including but not limited to horror, gore, sexually suggestive material, and monetary transactions. Delete such messages whenever they appear; impose a ten-minute mute for the first offense and removal for the next.</p><p><strong>Personal attacks are prohibited</strong>; do not delete them. Give a warning for the first offense, a two-hour mute for the next, and removal for another. A moderator&#39;s first offense receives a two-hour mute in the relevant group; a repeat offense results in loss of moderation privileges and a one-day mute in all groups.</p><p>Once membership reaches 475, tag everyone in the morning <span class="mark-grey">(approximately 4:00–12:00)</span> to announce an upcoming cleanup and coordinate across the support groups. In the evening <span class="mark-grey">(approximately 18:00–24:00, mainly to leave enough time between notice and action)</span>, <strong>remove inactive members</strong>: anyone without a title who has not spoken for over a week.</p><p>If <strong>support staff do not want to answer a question</strong>, they may ignore it <span class="mark-grey">(if not tagged)</span> or explicitly say they do not know or lack time <span class="mark-grey">(if tagged)</span>. Once they choose to answer, however, <span class="mark-grey">they must respect the other person&#39;s difficulties and questions throughout</span> and take full responsibility for their support. If they cannot solve a problem, identify who will follow up and clearly inform the questioner before handing it over. Do not vent frustration or abandon the consultation. Unjustified abandonment receives a warning the first time; a second offense in the near term results in loss of moderation privileges.</p><p>With the consent of at least two moderators, a <strong>bot may be invited into the group</strong>, but it must be closely managed. Inviting one without consent receives a warning and removal of the bot the first time; a repeat offense results in removal of both inviter and bot. If a bot disrupts Q&amp;A, treat it immediately as an ordinary member disrupting Q&amp;A. After the consultation, discuss in the support-team group whether the bot&#39;s owner should be penalized <span class="mark-grey">(the moderators did agree to let it in, after all)</span>.</p><p>A <strong>repeat offense</strong> usually means another violation within two to three days. When successive offenses break different rules, penalties should escalate progressively except where a first offense calls for a warning. For example, after two consecutive personal attacks trigger a two-hour mute, disrupting Q&amp;A should lead directly to a one-day mute instead of restarting at ten minutes. Conversely, after disruption has reached a one-hour mute, inviting an unauthorized bot should first receive a warning rather than immediate removal <span class="mark-grey">(first-offense warning)</span>; another unauthorized bot invitation leads to removal.</p><p><span id="source-block-FgIi5lmzQCSeiBKEktSP0f"></span></p><h2 id="clearing-inactive-members-from-the-qq-q-a-group" tabindex="-1">Clearing Inactive Members from the QQ Q&amp;A Group, <a class="header-anchor" href="#clearing-inactive-members-from-the-qq-q-a-group" aria-label="Permalink to &quot;Clearing Inactive Members from the QQ Q&amp;A Group,&quot;">​</a></h2><p><span class="mark-grey">#言: Clear out members who have not spoken for a week, once a week. Those wanting further study can message sky to join a dedicated group. Could people who want to stay and help get a group title? If their problem is still unresolved, they can rejoin.</span></p><p><span class="mark-grey">#东: What are the removal criteria? Not speaking for a long time? Keeping only a fixed roster?</span></p><p><span class="mark-grey">#disadvantage: In theory, people can be removed once troubleshooting is finished. Those wanting a deeper understanding can stay or move to another group.</span></p><p><span id="source-block-K1QLU97ywaQqerFz7hD7qK"></span></p><h2 id="customer-support-q-a-sign-up" tabindex="-1">Customer Support / Q&amp;A Sign-up <a class="header-anchor" href="#customer-support-q-a-sign-up" aria-label="Permalink to &quot;Customer Support / Q&amp;A Sign-up&quot;">​</a></h2><p><span id="source-block-n2NeK8zgbi9dRIjBQcTKpl"></span></p><h2 id="customer-support-q-a-roster" tabindex="-1">Customer Support / Q&amp;A Roster <a class="header-anchor" href="#customer-support-q-a-roster" aria-label="Permalink to &quot;Customer Support / Q&amp;A Roster&quot;">​</a></h2><p>jmy</p><p>东弓（东弓与葛冰之）</p><p>NH（D-15191）</p><p>凯尔希思衡托</p><p>SSnighter</p><p>Disadvantages</p><p>泥岩___（沃沃头子）</p><p>软柠</p><p><span id="source-block-9fU6RZ0Clraa1KB7ThLxkv"></span></p><h2 id="backup-q-a-roster" tabindex="-1">Backup Q&amp;A Roster <a class="header-anchor" href="#backup-q-a-roster" aria-label="Permalink to &quot;Backup Q&amp;A Roster&quot;">​</a></h2><p><span class="mark-grey">#东: I do feel that something is missing here.</span></p><p>泥岩___（沃沃头子）</p><p>#东: Anyone who can properly fix the 336 Cuprium consumption issue is the support team&#39;s last line of defense!</p><p><a href="/endfield-skydoc/automatic-support-bot-discussion">Discussion of an Automatic Support Bot</a></p></div>',1)])])}const m=t(n,[["render",r]]);export{c as __pageData,m as default};
